import osimport randomfrom langchain_core.tools import toolfrom rag.rag_service import RagSummarizeServicefrom utils.config_handler import agent_conffrom utils.logger_handler import loggerfrom utils.path_tool import get_abs_pathrag = RagSummarizeService()user_ids = ["1001", "1002", "1003", "1004", "1005", "1006", "1007", "1008", "1009", "1010"]month_arr = ["2025-01", "2025-02", "2025-03", "2025-04", "2025-05", "2025-06", "2025-07", "2025-08", "2025-09", "2025-10", "2025-11", "2025-12"]external_data = {}@tooldef rag_summarize(query: str) -> str:    """    从向量检索中检索参考资料    """    return rag.rag_summarize(query)@tooldef get_weather(city: str) -> str:    """    查询指定城市的实时天气、温度、湿度、风速、空气质量和未来几小时降雨概率。    Args:         city: 是城市名称，例如深圳、北京、上海。    Returns:        已指定字符串返回    """    return f"城市{city}天气为晴天，气温26摄氏度，空气湿度50%，南风1级，AQI21，最近6小时降雨概率极低"@tooldef get_user_location() -> str:    """    根据运行Agent的公网IP获取所在城市名称，以纯字符串形式返回。    """    return random.choice(["深圳", "合肥", "杭州"])@tooldef get_user_id() -> str:    """获取用户ID，以纯字符串形式返回"""    return random.choice(user_ids)@tooldef get_current_month() -> str:    """获取当前月份，以纯字符串形式返回"""    return random.choice(month_arr)def generate_external_data():    """    {        "user_id": {            "month": {"特征": xxx, "效率": xxx, ...}            "month": {"特征": xxx, "效率": xxx, ...}            ...        }        "user_id": {            "month": {"特征": xxx, "效率": xxx, ...}            ...        }        ...    }    """    # 第一次调用写入，后续不写入    if not external_data:        external_data_path = get_abs_path(agent_conf["external_data_path"])        if not os.path.exists(external_data_path):            raise FileNotFoundError(f"外部数据文件{external_data_path}不存在")        with open(external_data_path, "r", encoding='utf-8') as f:            # 不要第一行            for line in f.readlines()[1:]:                arr: list[str] = line.strip().split(",")                user_id = arr[0].replace('"', "")                feature: str = arr[1].replace('"', "")                efficiency: str = arr[2].replace('"', "")                consumable: str = arr[3].replace('"', "")                comparison: str = arr[4].replace('"', "")                time: str = arr[5].replace('"', "")                if user_id not in external_data:                    external_data[user_id] = {}                """                这里写的有一些问题，如果csv文件中一个user_id出现两个相同的时间，存入字典会覆盖前面的内容                """                external_data[user_id][time] = {                    "特征": feature,                    "效率": efficiency,                    "耗材": consumable,                    "对比": comparison,                }@tooldef fetch_external_data(user_id: str, month: str) -> str:    """从外部系统中获取指定用户在指定月份的使用记录，以纯字符串形式返回，如果未检索到返回空字符串"""    generate_external_data()    try:        return external_data[user_id][month]    except KeyError:        logger.warning(f"[fetch_external_data]未能检测到用户：{user_id}在{month}的使用数据")        return ""@tooldef fill_context_for_report():    """无入参，无返回值，调用后触发中间件，自动为报告生成的场景注入上下文信息，为后续提示词切换提供上下文信息"""    return f"fill_context_for_report已调用"if __name__ == "__main__":    print(fetch_external_data.invoke({"user_id": "1001", "month": "2025-01"}))